#include <stdio.h>
#include <stdlib.h>

#define MAXN 100000

typedef struct {
    long long key;
    int priority;
    int count;
    int size;
    int left;
    int right;
} Node;

Node tree[MAXN + 1];
int nodes_used = 0;

unsigned int rng_state = 123456789u;

unsigned int next_random(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

int subtree_size(int node) {
    return node ? tree[node].size : 0;
}

void update(int node) {
    tree[node].size = tree[node].count
                    + subtree_size(tree[node].left)
                    + subtree_size(tree[node].right);
}

int rotate_right(int root) {
    int child = tree[root].left;
    tree[root].left = tree[child].right;
    tree[child].right = root;
    update(root);
    update(child);
    return child;
}

int rotate_left(int root) {
    int child = tree[root].right;
    tree[root].right = tree[child].left;
    tree[child].left = root;
    update(root);
    update(child);
    return child;
}

int insert(int root, long long key) {
    if (!root) {
        int node = ++nodes_used;
        tree[node].key = key;
        tree[node].priority = (int)next_random();
        tree[node].count = 1;
        tree[node].size = 1;
        tree[node].left = tree[node].right = 0;
        return node;
    }

    if (key == tree[root].key) {
        tree[root].count++;
    } else if (key < tree[root].key) {
        tree[root].left = insert(tree[root].left, key);
        if ((unsigned int)tree[tree[root].left].priority >
            (unsigned int)tree[root].priority) {
            root = rotate_right(root);
        }
    } else {
        tree[root].right = insert(tree[root].right, key);
        if ((unsigned int)tree[tree[root].right].priority >
            (unsigned int)tree[root].priority) {
            root = rotate_left(root);
        }
    }

    update(root);
    return root;
}

int count_at_most(int root, long long key) {
    int result = 0;

    while (root) {
        if (key < tree[root].key) {
            root = tree[root].left;
        } else {
            result += subtree_size(tree[root].left) + tree[root].count;
            root = tree[root].right;
        }
    }

    return result;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int root = 0;
    int previous_penalty = 0;

    for (int i = 0; i < n; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        x += previous_penalty;
        y += previous_penalty;

        long long distance_squared = x * x + y * y;
        int penalty = count_at_most(root, distance_squared);

        printf("%d\n", penalty);
        root = insert(root, distance_squared);
        previous_penalty = penalty;
    }

    return 0;
}
